// Keep every version of a tree through 200 random inserts, and count the nodes it costs.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

let made = 0;                       // nodes allocated so far, across all versions
const node = (val, left, right) => { made++; return { val, left, right }; };
// Path copying, as in the Clojure cell.
function insert(t, v) {
  if (!t) return node(v, null, null);
  if (v < t.val) return node(t.val, insert(t.left, v), t.right);
  if (v > t.val) return node(t.val, t.left, insert(t.right, v));
  return t;
}
const size = t => (t ? 1 + size(t.left) + size(t.right) : 0);
const height = t => (t ? 1 + Math.max(height(t.left), height(t.right)) : 0);

const rand = mulberry32(107);
const versions = [null];
let fullCopies = 0, perInsert = 0;
const rows = [];
for (let k = 1; k <= 200; k++) {
  const before = made;
  const next = insert(versions.at(-1), Math.floor(rand() * 1000));
  versions.push(next);
  perInsert += made - before;
  fullCopies += size(next);           // what keeping every version as a full copy would cost
  if (k % 5 === 0) {
    rows.push({ inserts: k, nodes: made, way: 'path copying (persistent)' });
    rows.push({ inserts: k, nodes: fullCopies, way: 'a full copy per version' });
  }
}
const last = versions.at(-1);
console.log('200 inserts kept as 201 versions');
console.log('nodes with path copying: ' + made + '   with a full copy each: ' + fullCopies +
  '   (' + (fullCopies / made).toFixed(0) + ' times as many)');
console.log('nodes made per insert: ' + (perInsert / 200).toFixed(2) + ' on average; final tree: ' +
  size(last) + ' values, height ' + height(last));
console.log('the oldest versions are untouched: version 10 still has ' + size(versions[10]) + ' values');

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Memory for keeping every version',
  data: { values: rows },
  mark: { type: 'line', strokeWidth: 2 },
  encoding: {
    x: { field: 'inserts', type: 'quantitative', title: 'inserts (one new version each)' },
    y: { field: 'nodes', type: 'quantitative', scale: { type: 'log' }, title: 'tree nodes in memory (log scale)' },
    color: { field: 'way', type: 'nominal', title: null },
  },
};
